# Build the four Castkit 3-panel sheet prompts (16:9 in the tool) from the face-lock identity paragraphs.
close = open('close.txt', encoding='utf-8').read().strip()
close = close.replace('The background is a single flat 18% neutral gray field', 'Across all three panels identically, the background is a single flat 18% neutral gray field', 1)
A = ("LEFT PANEL — full body front view, no head, no neck, and no hair. The body faces the camera dead-on from the shoulders down to the shoes — shoulders and hips both square to the lens and level, both sides of the figure equally visible, arms relaxed at the sides, hands open and loose, feet planted parallel and pointing straight at camera, weight even across both feet. This is a flat frontal view regardless of how the figure stands in the reference: no three-quarter turn, no rotation of the torso or hips away from the lens, no twist at the waist, no contrapposto, no weight shifted onto one hip, no shoulder dropped or pushed forward, no foot turned out. There is no head, no neck, and no hair at all — nothing rises above the shoulder line, and no hair falls across the chest or shoulders. {collar} holds its own three-dimensional shape at the top of the garment and its opening is an empty dark hollow looking down into the inside of the garment, with the inner back of the fabric faintly visible inside the opening. The garment reads as worn by an invisible body — full volume, natural drape, real fabric tension across the chest and shoulders, but nothing emerging from the neckline. No stump, no skin, no cut edge, no anatomy, no blood, not blurred, not faded, not dissolving, no wisps, no smoke, no ghosting, no transparency in the body. The panel keeps full headroom — generous empty field above the shoulders where the head would be — so the figure sits at the same scale and position in the frame as a normal full-body portrait.{extra}")
B = ("LEFT PANEL — full body front view, headless. The full figure faces the camera dead-on from the shoulders down to the shoes — shoulders and hips both square to the lens and level, both sides of the figure equally visible, arms relaxed at the sides, hands open and loose, feet planted parallel and pointing straight at camera, weight even across both feet. This is a flat frontal view regardless of how the figure stands in the reference: no three-quarter turn, no rotation of the torso or hips away from the lens, no twist at the waist, no contrapposto, no weight shifted onto one hip, no shoulder dropped or pushed forward, no foot turned out. There is no head and no hair — no hair falls across the chest or shoulders. The neck rises a short way from the shoulders and terminates in a clean, flat, sharply defined horizontal edge at the base of the throat, exactly like a headless dress-form mannequin — a crisp sculptural cut with a clean visible edge, not blurred, not faded, not dissolving, no wisps, no smoke, no ghosting, no transparency, no blood, no anatomy detail at the cut. Above that clean edge there is only empty field. The panel keeps full headroom — generous empty space above the shoulders where the head would be — so the figure sits in the frame at the same scale and position as a normal full-body portrait.")
CENTER = ("CENTER PANEL — full body rear, head attached. The complete figure from above the crown down to the shoes, seen dead-on from directly behind — shoulders and hips square to the lens and level, the spine centered in the panel, arms relaxed at the sides, feet parallel, weight even. This is a flat rear view: no three-quarter turn, no rotation, no twist at the waist, no weight shifted onto one hip, no glance back over the shoulder. {back}")
RIGHT = ("RIGHT PANEL — tight chest-up face lock. Framed from just above the crown down to the collarbones with the face filling the panel. The head is dead-on to camera, squared and level, both ears equally visible, the nose centered between the eyes, eyes directly into the lens, neutral expression, lips closed and relaxed. This is a flat frontal view: no three-quarter turn, no head rotation, no chin lifted or dropped, no tilt to either side. {bottom} Every facial plane, the eyes, brows, nose, lips, and hairline read at maximum detail.")
OPEN = "A three-panel character reference sheet composed as one horizontal frame, divided into three equal vertical panels side by side with thin clean separation, the same figure and the same outfit rendered identically across all three. No text, no labels, no numbering anywhere in the image."
SKIN = "Skin renders at its true natural tone, identical in value and hue across the face, arms, hands, back, and body in every panel, never darkened, never pale or cool-shifted."

cast = {
    'rafa': dict(young="He has the youthful face and build of a college freshman athlete.", variant='A',
        collar="The ribbed crew collar of the cut-off tee", extra="",
        ward="He wears a heather-grey cotton practice tee with the sleeves cut off raggedly at the shoulder seams and a ribbed crew collar, faded and sweat-darkened at the chest, loose over black nylon mesh shorts that end just above the knee, white crew socks, and white low-top competition cheer shoes with thick soles. White athletic tape wraps both wrists. No jewelry other than the silver ear stud.",
        back="The close-cropped hair and taper from behind, the raw cut edges of the tee at the shoulders, the back of the shorts and the heels of the cheer shoes.",
        bottom="The ribbed crew collar of the grey cut-off tee enters at the bottom of frame."),
    'tess': dict(young="She has the youthful face and build of a college freshman athlete.", variant='B', collar="", extra="",
        ward="She wears a black compression sports bra with a wide scoop neck and a racer back, black high-waisted spandex shorts, white no-show socks, and white low-top competition cheer shoes with thick soles. A large red grosgrain cheer bow sits at the base of the high ponytail. White athletic tape wraps two fingers of each hand. No jewelry other than the three silver ear hoops.",
        back="The high ponytail and red bow from behind, the racer-back straps of the sports bra, the back of the spandex shorts and the heels of the cheer shoes.",
        bottom="The thin straps of the black sports bra enter at the bottom of frame."),
    'marcus': dict(young="He has the youthful face and build of a college sophomore athlete.", variant='A',
        collar="The ribbed collar of the tank", extra="",
        ward="He wears a heather-grey ribbed cotton tank with a ribbed collar at the collarbone, navy nylon mesh shorts that end just above the knee, a black neoprene brace on the left ankle over a white crew sock, a plain white crew sock on the right, and white low-top competition cheer shoes with thick soles. No jewelry other than the gold ear hoop.",
        back="The fade and twists from behind, the cut of the tank across the shoulder blades, the back of the shorts, the ankle brace and the heels of the cheer shoes.",
        bottom="The ribbed collar of the grey tank enters at the bottom of frame."),
    'lorraine': dict(young="", variant='A',
        collar="The zipped stand collar of the windbreaker",
        extra=" The silver whistle on its red woven lanyard still hangs from around the empty collar opening, resting on the front of the windbreaker.",
        ward="She wears a navy nylon team windbreaker with a single red stripe across the chest and down each sleeve, zipped all the way up into a stand collar, navy track pants with a thin red side stripe, and worn white leather trainers. The silver whistle hangs on its red woven lanyard over the windbreaker. A plain steel wristwatch on the left wrist.",
        back="The tight low knot of hair at the nape from behind, the back panel of the windbreaker, the back of the track pants and the heels of the trainers.",
        bottom="The zipped stand collar of the navy windbreaker and the red lanyard enter at the bottom of frame."),
}

for name, c in cast.items():
    ident = open(f'face-lock-{name}.txt', encoding='utf-8').read().split('\n\n')[1].strip()
    if c['young']:
        ident += ' ' + c['young']
    left = A.format(collar=c['collar'], extra=c['extra']) if c['variant'] == 'A' else B
    parts = [OPEN, ident, c['ward'], left, CENTER.format(back=c['back']), RIGHT.format(bottom=c['bottom']), SKIN, close]
    open(f'sheet-{name}.txt', 'w', encoding='utf-8').write('\n\n'.join(parts) + '\n')
    print(name, len(' '.join(parts).split()), 'words')
